<script setup lang="ts">
import {locale,tr} from '../lib/i18n'
import ProfileFlow from './ProfileFlow.vue'
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
const publicProfile=ref(false)
import {api,apiBaseUrl} from '../lib/api'
import {asset} from '../lib/assets'
const props=defineProps<{token:string;conversation:{id:string;displayName:string;remark?:string;status:string;peerId?:string;hidden?:boolean}}>()
const emit=defineEmits<{close:[];collect:[]}>()
type Message={id:string;content:string;kind:string;createdAt:string;senderId?:string;mine?:boolean;mediaId?:string;media?:{url:string;kind:string}[]}
const rows=ref<Message[]>([]),pending=ref(false),open=ref(props.conversation.status==='open'),draft=ref(sessionStorage.getItem('chat-draft-'+props.conversation.id)||''),screen=ref('chat'),query=ref(''),results=ref<Message[]>([]),searched=ref(false),remark=ref(props.conversation.remark||''),error=ref(''),busy=ref(false),stickers=ref(false),selected=ref(''),photo=ref<File>(),preview=ref(''),record=ref(''),micDenied=ref(false),sent=ref(false),cleared=ref(false),confirm=ref(false),editing=ref(false),more=ref(false)
const safety=ref(''),blocked=ref(false),safetyReady=ref(false),reason=ref('harassment'),reportDetails=ref(''),reportSaved=ref(false)
const safetyState=computed(()=>safety.value==='choice'?'safety-choice':safety.value==='confirm'?(blocked.value?'unblock-confirm':'block-confirm'):screen.value==='report'?(reportDetails.value?'report-filled':'report-empty'):reportSaved.value?'report-saved':screen.value==='chat'&&blocked.value?'chat-blocked':'')
async function permissions(){const r=await request<{items:{userId:string}[]}>('/blocks');blocked.value=r.items.some(b=>b.userId===props.conversation.peerId);safetyReady.value=true}
async function changeBlock(){if(busy.value)return;busy.value=true;error.value='';try{await request(`/blocks/${props.conversation.peerId}`,blocked.value?'DELETE':'PUT');await permissions();if(blocked.value){leaveVoice();discardVoice();photo.value=undefined;selected.value='';stickers.value=false;draft.value=''}else{for(let offset=0;;offset+=100){const r=await request<{items:{id:string;status:string}[];hasMore?:boolean}>(`/conversations?hidden=${!!props.conversation.hidden}&limit=100&offset=${offset}`);const c=r.items.find(c=>c.id===props.conversation.id);if(c){open.value=c.status==='open';break}if(!r.hasMore)break}await load()}safety.value='';screen.value='chat';reportSaved.value=false}catch(e){fail(e)}finally{busy.value=false}}
const reportMediaId=ref(''),reportPreview=ref(''),reportUploading=ref(false),reportUploadError=ref(''),savedWithPhoto=ref(false)
let reportUploadVersion=0
function removeReportPhoto(){reportUploadVersion++;reportMediaId.value='';if(reportPreview.value)URL.revokeObjectURL(reportPreview.value);reportPreview.value='';reportUploading.value=false;reportUploadError.value=''}
async function chooseReportPhoto(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];input.value='';if(!f)return;removeReportPhoto();if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>=10*1024*1024){reportUploadError.value='Choose a PNG, JPEG or WebP image smaller than 10 MB. You can still submit without a photo.';return}const version=reportUploadVersion;reportPreview.value=URL.createObjectURL(f);reportUploading.value=true;try{const q=new URLSearchParams({purpose:'report',filename:f.name});const media=await api<{id:string}>(`/media/uploads?${q}`,{method:'POST',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':f.type},body:f});if(version===reportUploadVersion)reportMediaId.value=media.id}catch(e){if(version===reportUploadVersion)reportUploadError.value=`Photo upload failed. ${(e as Error).message} You can still submit without a photo.`}finally{if(version===reportUploadVersion)reportUploading.value=false}}
async function saveReport(){if(busy.value)return;busy.value=true;error.value='';try{const attachmentMediaId=reportMediaId.value;await request('/reports','POST',{...(attachmentMediaId?{attachmentMediaId}:{}),reportedUserId:props.conversation.peerId,category:reason.value,reason:reportDetails.value.trim()||({harassment:'Abuse or harassment',spam:'Spam or advertising',sexual:'Inappropriate content',other:'Something else'}[reason.value]||reason.value)});savedWithPhoto.value=!!attachmentMediaId;removeReportPhoto();screen.value='details';reportSaved.value=true}catch(e){fail(e)}finally{busy.value=false}}
const wallpapers=[['moon-road','Moonlit road'],['glowing-deer','Forest glow'],['blue-cosmos','Blue cosmos'],['little-soot','Little soot'],['night-glass','Night glass'],['sunset-peak','Sunset peak'],['silver-feather','Silver feather'],['aurora-sky','Aurora sky']]
const themes=['night','forest','clouds','lavender','sunset','ocean','stars']
const bubbleFields=[['myBubble','My bubble','#aef879'],['myText','My text','#153011'],['theirBubble','Their bubble','#28362e'],['theirText','Their text','#e1e9dd']]
const appearanceKey='maugo-chat-appearance-'+props.conversation.id
const appearance=ref<Record<string,string>>(JSON.parse(localStorage.getItem(appearanceKey)||'{}'))
if(appearance.value.wallpaperId&&!wallpapers.some(w=>w[0]===appearance.value.wallpaperId)){delete appearance.value.wallpaperId;appearance.value.background='night';localStorage.setItem(appearanceKey,JSON.stringify(appearance.value))}
const appearanceTab=ref('wallpapers'),previewWallpaper=ref(wallpapers[0]!)
watch(appearance,v=>localStorage.setItem(appearanceKey,JSON.stringify(v)),{deep:true,flush:'sync'})
const appearanceState=computed(()=>screen.value==='background'?(appearanceTab.value==='colors'?'wallpaper-colors':'wallpapers'):screen.value==='wallpaper-preview'?'wallpaper-preview':screen.value==='bubbles'?(bubbleFields.some(f=>appearance.value[f[0]!]&&appearance.value[f[0]!]!==f[2])?'chat-bubbles-custom':'chat-bubbles'):screen.value==='chat'&&(appearance.value.wallpaperId||appearance.value.background&&appearance.value.background!=='night')?'wallpaper-applied':'')
const appearanceStyle=computed(()=>({'--my-bubble':appearance.value.myBubble||'#aef879','--my-text':appearance.value.myText||'#153011','--their-bubble':appearance.value.theirBubble||'#28362e','--their-text':appearance.value.theirText||'#e1e9dd',...(screen.value==='chat'&&appearance.value.wallpaperId?{backgroundImage:`linear-gradient(#07100b26,#07100b26),url("${asset('04-chat-backgrounds/'+appearance.value.wallpaperId)}")`}:{})}))
function applyBackground(theme:string,wallpaperId=''){appearance.value.background=theme;if(wallpaperId)appearance.value.wallpaperId=wallpaperId;else delete appearance.value.wallpaperId;screen.value='chat'}
function resetBubbles(){for(const f of bubbleFields)delete appearance.value[f[0]!]}
const state=computed(()=>safetyState.value||appearanceState.value|| (confirm.value?'chat-clear-confirm':editing.value?'chat-remark':screen.value==='details'?(open.value?'chat-details':'chat-details-waiting'):screen.value==='search'?(!query.value?'chat-search-empty':searched.value&&results.value.length?'chat-search-result':'chat-search-none'):record.value==='cancel'?'chat-record-cancel':record.value?'chat-recording':micDenied.value?'chat-mic-denied':!open.value?(pending.value?'chat-receipt-waiting':'chat-waiting'):photo.value?'chat-attachment':selected.value?'chat-sticker-selected':stickers.value?'chat-stickers':draft.value?'chat-draft':sent.value?'chat-sent':cleared.value?'chat-cleared':rows.value.some(m=>m.media?.length)?'chat-photo':'chat-open'))
function request<T>(path:string,method='GET',body?:object){return api<T>(path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})})}
function fail(e:unknown){error.value=(e as Error).message}
const objectURLs:string[]=[]
async function load(append=false){try{const r=await request<{items:Message[];hasMore?:boolean}>(`/conversations/${props.conversation.id}/messages?markRead=true&limit=20&offset=${append?rows.value.length:0}`);for(const m of r.items){const path=m.mediaId?`/media/uploads/${m.mediaId}`:/^\/media\/uploads\/[0-9a-f-]+$/.test(m.content)?m.content:undefined;if(path){const response=await fetch(apiBaseUrl+path,{headers:{Authorization:`Bearer ${props.token}`}});if(!response.ok)throw Error('Unable to load photo.');const url=URL.createObjectURL(await response.blob());objectURLs.push(url);m.media=[{url,kind:response.headers.get('Content-Type')?.startsWith('audio/')?'audio':'image'}];m.content=''}}rows.value=append?[...rows.value,...r.items]:r.items;more.value=!!r.hasMore;const q=await request<{items:{id:string}[]}>(`/conversations/${props.conversation.id}/replies/pending`);pending.value=q.items.length>0}catch(e){fail(e)}}
function gate(){if(!safetyReady.value||blocked.value){error.value='Unblock this person to continue.';return false}if(!open.value){error.value='Photos, voice and stickers unlock after they reply.';return false}return true}
async function send(){if(busy.value||!gate()||(!draft.value.trim()&&!photo.value&&!selected.value))return;busy.value=true;error.value='';try{let mediaId:string|undefined;const attachment=photo.value||(selected.value?new File([await (await fetch(asset('06-stickers/'+selected.value))).blob()],'sticker.png',{type:'image/png'}):undefined);if(attachment){const q=new URLSearchParams({purpose:'chat',conversationId:props.conversation.id,filename:'photo.'+(attachment.type==='image/png'?'png':attachment.type==='image/webp'?'webp':'jpg')});const upload=(path:string)=>api<{id:string}>(path,{method:'POST',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':attachment.type},body:attachment});const r=await upload(`/media/uploads?${q}`);mediaId=r.id}const content=draft.value.trim();let r:{id:string};if(mediaId){r=await request<{id:string}>(`/conversations/${props.conversation.id}/media`,'POST',{mediaId});if(content)await request(`/conversations/${props.conversation.id}/messages`,'POST',{content})}else{r=await request<{id:string}>(`/conversations/${props.conversation.id}/messages`,'POST',{content})}rows.value.push({id:r.id,content,kind:'reply',mine:true,createdAt:new Date().toISOString(),...(attachment?{media:[{url:photo.value?preview.value:asset('06-stickers/'+selected.value),kind:'image'}]}:{})});draft.value='';selected.value='';photo.value=undefined;stickers.value=false;sent.value=true;cleared.value=false}catch(e){fail(e)}finally{busy.value=false}}
function choose(e:Event){if(!gate())return;const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>=10*1024*1024){error.value='Choose an image smaller than 10 MB.';return}photo.value=f;preview.value=URL.createObjectURL(f);objectURLs.push(preview.value)}
const voice=ref<Blob>(),voiceURL=ref(''),seconds=ref(0),voiceNotice=ref(''),uploadFailed=ref(false)
const voiceTime=computed(()=>`${Math.floor(seconds.value/60)}:${String(Math.floor(seconds.value%60)).padStart(2,'0')}`)
let startY=0,holding=false,generation=0,stream:MediaStream|undefined,context:AudioContext|undefined,source:MediaStreamAudioSourceNode|undefined,processor:ScriptProcessorNode|undefined,ticker:ReturnType<typeof setInterval>|undefined,started=0,sampleRate=44100,samples:Float32Array[]=[],peak=0,uploadedId:string|undefined
function cleanup(){clearInterval(ticker);processor?.disconnect();source?.disconnect();stream?.getTracks().forEach(t=>t.stop());void context?.close();processor=undefined;source=undefined;stream=undefined;context=undefined;samples=[]}
function discardVoice(){if(voiceURL.value)URL.revokeObjectURL(voiceURL.value);voiceURL.value='';voice.value=undefined;uploadedId=undefined;uploadFailed.value=false}
function cancelVoice(){holding=false;generation++;record.value='';cleanup();discardVoice();voiceNotice.value='Recording cancelled. No audio was sent.'}
function wav(chunks:Float32Array[],rate:number){const length=chunks.reduce((n,c)=>n+c.length,0),buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer);const str=(o:number,t:string)=>{for(let i=0;i<t.length;i++)v.setUint8(o+i,t.charCodeAt(i))};str(0,'RIFF');v.setUint32(4,36+length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*2,true);let offset=44;for(const chunk of chunks)for(const sample of chunk){v.setInt16(offset,Math.max(-1,Math.min(1,sample))*32767,true);offset+=2}return new Blob([buffer],{type:'audio/wav'})}
async function hold(e:PointerEvent){if(!gate()||busy.value||record.value||voice.value)return;startY=e.clientY;holding=true;const version=++generation;micDenied.value=false;voiceNotice.value='';error.value='';record.value='requesting';(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('unavailable');const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(version!==generation||!holding){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;context=new AudioContext();await context.resume();if(version!==generation||!holding){cleanup();return}sampleRate=context.sampleRate;source=context.createMediaStreamSource(stream);processor=context.createScriptProcessor(4096,1,1);samples=[];peak=0;processor.onaudioprocess=event=>{const remaining=Math.max(0,Math.floor(sampleRate*60)-samples.reduce((n,c)=>n+c.length,0));const data=new Float32Array(event.inputBuffer.getChannelData(0).subarray(0,remaining));samples.push(data);for(const x of data)peak=Math.max(peak,Math.abs(x));seconds.value=samples.reduce((n,c)=>n+c.length,0)/sampleRate};source.connect(processor);processor.connect(context.destination);started=performance.now();seconds.value=0;if(record.value!=='cancel')record.value='recording';ticker=setInterval(()=>{if(performance.now()-started>=60000){voiceNotice.value='60 second limit reached. Preview your recording.';finishVoice()}},100)}catch(e){if(version!==generation)return;holding=false;record.value='';cleanup();micDenied.value=true;const name=(e as Error).name;voiceNotice.value=name==='NotAllowedError'||name==='SecurityError'?'Microphone permission denied. Allow microphone access in browser settings and try again.':`Microphone unavailable. Connect a microphone and try again. (${(e as Error).name}: ${(e as Error).message})`}}
function move(e:PointerEvent){if(holding&&record.value)record.value=startY-e.clientY>65?'cancel':processor?'recording':'requesting'}
function finishVoice(){if(record.value==='cancel'){cancelVoice();return}holding=false;generation++;record.value='';const chunks=samples,level=peak;seconds.value=chunks.reduce((n,c)=>n+c.length,0)/sampleRate;cleanup();if(seconds.value<0.5||level<0.008){voiceNotice.value='Recording too short or no sound detected. Please record again.';return}voice.value=wav(chunks,sampleRate);voiceURL.value=URL.createObjectURL(voice.value)}
function release(){if(holding)finishVoice()}
async function sendVoice(){if(!voice.value||busy.value||!gate())return;busy.value=true;uploadFailed.value=false;voiceNotice.value='';try{if(!navigator.onLine)throw Error('You are offline. Reconnect and retry.');if(!uploadedId){const q=new URLSearchParams({purpose:'chat',conversationId:props.conversation.id,filename:'voice.wav'});uploadedId=(await api<{id:string}>(`/media/uploads?${q}`,{method:'POST',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'audio/wav'},body:voice.value})).id}const result=await request<{id:string}>(`/conversations/${props.conversation.id}/media`,'POST',{mediaId:uploadedId});objectURLs.push(voiceURL.value);rows.value.push({id:result.id,kind:'audio',content:'',mine:true,createdAt:new Date().toISOString(),media:[{url:voiceURL.value,kind:'audio'}]});voice.value=undefined;voiceURL.value='';uploadedId=undefined;sent.value=true;voiceNotice.value='Voice message sent.'}catch(e){uploadFailed.value=true;voiceNotice.value=`Voice upload/send failed. ${(e as Error).message} Your recording is available to retry.`}finally{busy.value=false}}
function leaveVoice(){if(record.value)cancelVoice()}
function visibilityChange(){if(document.hidden)leaveVoice()}
watch(screen,leaveVoice)
async function patch(body:object){if(busy.value)return;busy.value=true;error.value='';try{await request(`/conversations/${props.conversation.id}`,'PATCH',body);if('clearHistory' in body){rows.value=[];cleared.value=true;sent.value=false;micDenied.value=false;confirm.value=false;screen.value='chat'}else{editing.value=false;props.conversation.remark=remark.value}}catch(e){fail(e)}finally{busy.value=false}}
let searchVersion=0,timer:ReturnType<typeof setTimeout>,poll:ReturnType<typeof setInterval>
watch(query,()=>{clearTimeout(timer);searched.value=false;const version=++searchVersion;results.value=[];if(!query.value.trim())return;timer=setTimeout(async()=>{try{const r=await request<{items:Message[]}>(`/conversations/${props.conversation.id}/messages?markRead=false&limit=50&offset=0&search=${encodeURIComponent(query.value.trim())}`);if(version===searchVersion){results.value=r.items;searched.value=true}}catch(e){if(version===searchVersion)fail(e)}},250)})
watch(()=>props.conversation.status,async status=>{if(status==='open'&&!open.value){await load();open.value=true}})
watch(draft,v=>sessionStorage.setItem('chat-draft-'+props.conversation.id,v))
function back(){if(safety.value){if(!busy.value)safety.value='';return}reportSaved.value=false;if(record.value)cancelVoice();if(voice.value&&!busy.value)discardVoice();if(confirm.value)confirm.value=false;else if(editing.value)editing.value=false;else if(screen.value==='wallpaper-preview')screen.value='background';else if(['background','bubbles'].includes(screen.value))screen.value='details';else if(screen.value!=='chat')screen.value='chat';else emit('close')}
onMounted(()=>{document.addEventListener('visibilitychange',visibilityChange);void permissions().catch(fail);void load();poll=setInterval(()=>{if(!open.value)void load()},4000)})
onUnmounted(()=>{document.removeEventListener('visibilitychange',visibilityChange);generation++;holding=false;cleanup();discardVoice();removeReportPhoto();clearInterval(poll);clearTimeout(timer);searchVersion++;objectURLs.forEach(url=>URL.revokeObjectURL(url))})
</script>
<template>
<ProfileFlow v-if="publicProfile" :token="token" :person="{...conversation,status:open&&!blocked&&safetyReady?'open':'waiting'}" @close="publicProfile=false" @chat="publicProfile=false;screen='chat'" @safety="publicProfile=false;screen=$event==='report'?'report':'details';safety=$event==='block'?'confirm':'';reportSaved=false" />
<section class="c6-chat" :data-state="state" :style="appearanceStyle" :class="[screen==='chat'&&(appearance.wallpaperId||appearance.background)?'theme-'+(appearance.wallpaperId?'wallpaper':appearance.background):'',{'safety-flow':!!safetyState,'safety-report-page':screen==='report','chat-details-flow':screen==='details'||screen==='search','chat-flow':screen==='chat','d2-custom-bubbles':bubbleFields.some(f=>appearance[f[0]!]),'d2-appearance':['background','wallpaper-preview','bubbles'].includes(screen)}]"><header class="ui-header"><button :class="{'ui-header__back':true,'ui-icon-button':['background','wallpaper-preview','bubbles','report'].includes(screen)}" :aria-label="tr('Back to messages')" @click="back"><img v-if="screen==='details'||screen==='search'||['background','wallpaper-preview','bubbles','report'].includes(screen)" :src="asset('08-interface-icons/icon-chevron-left-light-22')" alt=""><template v-else>‹</template></button><h1>{{screen==='report'?tr('Report'):screen==='background'?tr('Chat background'):screen==='wallpaper-preview'?tr('Preview wallpaper'):screen==='bubbles'?tr('Chat bubbles'):screen==='details'?tr('Chat details'):screen==='search'?tr('Search messages'):conversation.remark||conversation.displayName}}</h1><span v-if="['background','wallpaper-preview','bubbles','report'].includes(screen)" class="d2-header-space"></span><button v-if="!['background','wallpaper-preview','bubbles','report'].includes(screen)" :class="{'ui-header__back chat-details-button':screen==='chat'}" :style="screen==='details'||screen==='search'?{visibility:'hidden'}:undefined" id="chat-details" :aria-label="tr('Chat details')" @click="screen='details'">•••</button></header>
<p v-if="reportSaved" class="d3-saved" role="status">{{tr("Report received. Thank you for helping keep MauGo safe.")}}<span v-if="savedWithPhoto"> {{tr("Photo submitted with your report.")}}</span></p>
<p v-if="error" role="alert" class="c6-error">{{tr(error)}} <button @click="error='';load()">{{tr("Retry")}}</button></p>
<template v-if="screen==='chat'"><p class="chat-notice">{{tr("A kind space for a little conversation.")}}</p><div id="chat-thread" class="c6-thread"><button v-if="more" @click="load(true)">{{tr("Earlier messages")}}</button><TransitionGroup name="c6-message"><article v-for="m in rows" :key="m.id" class="chat-message" :class="{mine:m.mine}"><img v-if="!m.mine" :src="asset('05-avatars/avatar-placeholder')" alt=""><div class="chat-bubble" :class="{'chat-bubble--mine':m.mine}"><span>{{m.content}}</span><template v-for="media in m.media" :key="media.url"><audio class="chat-media-audio" v-if="media.kind==='audio'" :src="media.url" controls preload="metadata" :aria-label="tr('Voice message')"></audio><img class="chat-media-image" v-else :src="media.url" :alt="tr('Photo message')"></template></div><small class="chat-message-time" :class="{'chat-message-time--mine':m.mine}">{{new Date(m.createdAt).toLocaleTimeString(locale==='ko'?'ko-KR':'en-US',{hour:'2-digit',minute:'2-digit'})}}</small></article></TransitionGroup><p v-if="!rows.length" class="c6-empty">{{tr(cleared?'Chat history cleared. Your connection stays open.':'No messages yet.')}}</p></div>
<div class="d11-chat-gate"><Transition name="d11-unlock"><div v-if="blocked||!open||!safetyReady" key="waiting" class="waiting-card"><strong class="chat-waiting-title">{{tr(blocked?'Conversation blocked':pending?'A reply has arrived.':'Waiting for their reply')}}</strong><p class="chat-waiting-copy">{{tr(blocked?'Unblock this person to continue.':pending?'Collect your reply from Inbox to continue.':'Your one opening message is sent. More messages and interactions unlock after they reply.')}}</p><button class="ui-chat-link ui-chat-link--safety" v-if="blocked" @click="screen='details'">{{tr("View chat details")}}</button><button class="ui-chat-link" v-if="pending&&!blocked" @click="emit('collect')">{{tr("Collect your reply")}}</button></div>
<form v-else key="composer" id="chat-form" class="c6-composer" @submit.prevent="send"><div v-if="photo||selected" class="c6-attachment"><img class="chat-attachment-image" :src="photo?preview:asset('06-stickers/'+selected)" :alt="tr('Pending attachment')"><button class="ui-attachment-remove" type="button" :aria-label="tr('Remove attachment')" @click="photo=undefined;selected=''">{{tr(photo?'Photo':'Sticker')}} ×</button></div><div class="c6-input"><input class="ui-input ui-input--chat" id="chat-input" v-model="draft" maxlength="200" :aria-label="tr('Message')" :placeholder="tr('Say something kind…')"><button class="ui-icon-button ui-icon-button--chat-send" id="chat-send" :aria-label="tr('Send message')" :disabled="busy||(!draft.trim()&&!photo&&!selected)"><template v-if="busy">…</template><img v-else :src="asset('08-interface-icons/icon-send-dark-24')" alt=""></button></div><div class="chat-tools"><button class="ui-icon-button ui-icon-button--chat-tool" id="chat-stickers" type="button" :aria-label="tr('Stickers')" @click="gate()&&(stickers=!stickers)"><img :src="asset('08-interface-icons/icon-smile-muted-20')" alt=""></button><label class="c6-photo ui-icon-button ui-icon-button--chat-tool" :aria-label="tr('Photo')"><img :src="asset('08-interface-icons/icon-photo-muted-20')" alt=""><input id="chat-photo" type="file" accept="image/png,image/jpeg,image/webp" :aria-label="tr('Photo')" @change="choose"></label><button class="ui-button ui-button--chat-hold" id="chat-hold" type="button" @pointerdown.prevent="hold" @pointermove="move" @pointerup="release" @pointercancel="cancelVoice" :disabled="busy||!!voice"><img :src="asset('08-interface-icons/icon-microphone-muted-20')" alt="">{{tr("Hold to talk")}}</button></div><Transition name="c6-panel"><div v-if="stickers&&!selected" class="c6-stickers ui-sticker-picker"><div class="ui-sticker-picker__heading">{{tr("A feeling for this moment")}}<button type="button" class="ui-sticker-close" :aria-label="tr('Close emoji picker')" @click="stickers=false">×</button></div><div class="ui-sticker-grid"><button v-for="s in ['sticker-5-158', 'sticker-5-173', 'sticker-5-200', 'sticker-5-229', 'sticker-5-252', 'sticker-5-268', 'sticker-5-292', 'sticker-5-316', 'sticker-5-329', 'sticker-5-33', 'sticker-5-373', 'sticker-5-409', 'sticker-5-429', 'sticker-5-447', 'sticker-5-474', 'sticker-5-499', 'sticker-5-514', 'sticker-5-537', 'sticker-5-555', 'sticker-5-56', 'sticker-5-562', 'sticker-5-584', 'sticker-5-592', 'sticker-5-606', 'sticker-5-615', 'sticker-5-626', 'sticker-5-634', 'sticker-5-649', 'sticker-5-670', 'sticker-5-691', 'sticker-5-711', 'sticker-5-727', 'sticker-5-742', 'sticker-5-756', 'sticker-5-771', 'sticker-5-784', 'sticker-5-797', 'sticker-5-80', 'sticker-5-815', 'sticker-5-838', 'sticker-5-856', 'sticker-5-869', 'sticker-5-884', 'sticker-5-9', 'sticker-5-903', 'sticker-5-922', 'sticker-5-939', 'sticker-5-957', 'sticker-5-969', 'sticker-5-99']" :key="s" type="button" class="sticker-option ui-sticker-option" :aria-label="`${tr('Sticker')} ${s.split('-').at(-1)}`" @click="gate()&&(selected=s)"><img :src="asset('06-stickers/'+s)" :alt="tr('Sticker')"></button></div></div></Transition></form></Transition></div>
<Transition name="c6-panel"><div v-if="record" class="c6-record" :class="{cancel:record==='cancel'}" role="status"><div class="c6-wave" :class="{'c6-wave--cancel':record==='cancel'}" aria-hidden="true"><i class="chat-wave-bar" :class="{'chat-wave-bar--cancel':record==='cancel'}" v-for="bar in 26" :key="bar"></i></div><strong class="chat-record-hint">{{tr(record==='cancel'?'Release to cancel':'Slide up to cancel')}}</strong><p class="chat-record-time">{{tr(record==='requesting'?'Requesting microphone…':voiceTime+' / 1:00')}}</p><span class="chat-cancel-target" :class="{'chat-cancel-target--active':record==='cancel'}">{{tr('Slide here to cancel')}}</span><span class="chat-record-finish" :class="{'chat-record-finish--cancel':record==='cancel'}">{{tr('Release to finish')}}</span></div></Transition><Transition name="c6-panel"><div v-if="voice" class="c6-voice-preview"><strong>{{tr("Preview voice ·")}} {{voiceTime}}</strong><audio :src="voiceURL" controls :aria-label="tr('Preview voice')"></audio><div class="chat-voice-actions"><button type="button" :disabled="busy" @click="discardVoice();voiceNotice='Record again when ready.'">{{tr("Re-record")}}</button><button type="button" :disabled="busy" @click="discardVoice();voiceNotice='Recording cancelled. No audio was sent.'">{{tr("Cancel")}}</button><button id="voice-send" type="button" :disabled="busy" @click="sendVoice">{{tr(busy?'Sending…':uploadFailed?'Retry voice':'Send voice')}}</button></div></div></Transition><p v-if="voiceNotice" class="c6-voice-notice" role="status"><template v-if="micDenied">{{tr("Microphone access is off. You can still use text.")}}<span class="chat-accessible-notice">{{tr(voiceNotice)}}</span></template><template v-else>{{tr(voiceNotice)}}</template></p></template>
<template v-else-if="screen==='report'"><form class="d3-report" @submit.prevent="saveReport"><p class="d3-intro">{{tr("Tell us what happened.")}}</p><label class="safety-reason">{{tr("Reason")}}<select class="ui-input ui-input--safety" id="report-reason" v-model="reason"><option value="harassment">{{tr("Abuse or harassment")}}</option><option value="spam">{{tr("Spam or advertising")}}</option><option value="sexual">{{tr("Inappropriate content")}}</option><option value="other">{{tr("Something else")}}</option></select></label><label class="safety-details">{{tr("Details")}}<textarea class="ui-input ui-input--safety ui-input--safety-area" id="report-details" v-model="reportDetails" maxlength="500" :placeholder="tr('Add a little context…')"></textarea></label><label class="d3-add-photo ui-button ui-button--appearance-reset" :class="{'d3-photo-disabled':busy}">{{tr("Add a photo")}}<input id="report-photo" type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="chooseReportPhoto"></label><Transition name="c6-panel"><div v-if="reportPreview" id="report-attachment" class="safety-attachment"><img class="safety-attachment-image" :src="reportPreview" :alt="tr('Report attachment preview')"><button class="ui-button ui-button--text" type="button" :disabled="busy" @click="removeReportPhoto">{{tr("Remove attachment")}}</button></div></Transition><p v-if="reportUploading" role="status">{{tr("Uploading photo… Submitting now will send the report without a photo.")}}</p><p v-else-if="reportMediaId" role="status">{{tr("Photo ready to submit.")}}</p><p v-if="reportUploadError" class="d3-upload-error" role="alert">{{tr(reportUploadError)}}</p><p class="safety-report-note">{{tr("Your report will be sent to the MauGo moderation team.")}}</p><button id="save-report" class="ui-button ui-button--reply safety-report-save" :disabled="busy">{{tr(busy?'Saving…':'Save report')}}</button></form></template>
<template v-else-if="screen==='details'"><div class="chat-settings-body" :class="{'chat-settings-body--waiting':!open}"><div class="c6-person"><button id="view-public-profile" class="ui-avatar-button" :class="{'ui-avatar-button--waiting':!open}" :aria-label="tr('View profile ›')" @click="publicProfile=true"><img :src="asset(open?'05-avatars/avatar-placeholder':'01-brand-scenes/envelope-avatar')" alt=""></button><h2 class="chat-person-name">{{open?(conversation.remark||conversation.displayName):(locale==='ko'?'보낸 편지':'Your sent letter')}}</h2><p class="chat-person-note">{{tr(open?'You can now chat freely.':'More interactions unlock after they reply.')}}</p><button class="ui-button ui-button--chat-follow chat-follow" disabled>{{locale==='ko'?'팔로우':'Follow'}}</button><p v-if="!open" class="chat-follow-note">{{locale==='ko'?'답장이 오면 팔로우할 수 있어요.':'Following unlocks after they reply.'}}</p></div><div class="chat-settings-group ui-card ui-card--chat-settings"><button id="remark-name" class="c6-row ui-row" @click="editing=true">{{tr("Remark name")}} <span class="chat-row-value">{{remark}}</span><span class="ui-chevron">›</span></button><label class="ui-row ui-row--chat-toggle">{{locale==='ko'?'대화 고정':'Pin conversation'}}<input class="ui-switch" type="checkbox" disabled></label><button id="chat-background" class="c6-row ui-row" @click="screen='background';appearanceTab='wallpapers'">{{tr("Chat background")}} <span class="ui-chevron">›</span></button><button id="chat-bubbles" class="c6-row ui-row" @click="screen='bubbles'">{{tr("Chat bubbles")}} <span class="ui-chevron">›</span></button><button class="c6-row ui-row" :aria-label="tr('Search chat history')" @click="screen='search'">{{tr("Search messages")}} <span class="ui-chevron">›</span></button></div><div class="chat-settings-secondary ui-card ui-card--chat-settings"><label class="ui-row ui-row--chat-toggle">{{locale==='ko'?'알림 끄기':'Mute notifications'}}<input class="ui-switch" type="checkbox" disabled></label><button id="block-chat" class="c6-row ui-row" :disabled="!safetyReady" @click="safety='confirm';reportSaved=false">{{tr(blocked?'Unblock':'Block')}} <span class="ui-chevron">›</span></button><button id="report-person" class="c6-row ui-row" @click="safety='choice';reportSaved=false">{{tr("Report")}} <span class="ui-chevron">›</span></button><button id="clear-chat" :aria-label="tr('Clear chat history')" class="c6-row ui-row ui-row--danger" @click="confirm=true">{{locale==='ko'?'메시지 지우기':'Clear messages'}} <span class="ui-chevron">›</span></button></div></div></template>
<template v-else-if="screen==='background'||screen==='wallpaper-preview'||screen==='bubbles'">
<Transition name="d2-page" mode="out-in"><div :key="screen+appearanceTab" class="d2-body">
<template v-if="screen==='background'"><div class="page-tabs ui-appearance-tabs"><button id="wallpaper-tab" :class="{selected:appearanceTab==='wallpapers'}" @click="appearanceTab='wallpapers'">{{tr("Wallpapers")}}</button><button id="color-tab" :class="{selected:appearanceTab==='colors'}" @click="appearanceTab='colors'">{{tr("Colors")}}</button></div>
<template v-if="appearanceTab==='wallpapers'"><div class="wallpaper-grid"><button id="wallpaper-default" class="wallpaper-tile ui-wallpaper-tile wallpaper-default" :aria-pressed="!appearance.wallpaperId&&(!appearance.background||appearance.background==='night')" @click="applyBackground('night')"><span class="wallpaper-name ui-wallpaper-name">{{tr("Default")}}</span><b class="wallpaper-check" v-if="!appearance.wallpaperId&&(!appearance.background||appearance.background==='night')">✓</b></button><button v-for="w in wallpapers" :key="w[0]" class="wallpaper-tile ui-wallpaper-tile" :data-wallpaper="w[0]" :aria-label="tr(w[1])" :aria-pressed="appearance.wallpaperId===w[0]" @click="previewWallpaper=w;screen='wallpaper-preview'"><img class="appearance-tile-image" :src="asset('04-chat-backgrounds/'+w[0])" :alt="tr(w[1])" loading="lazy"><span class="wallpaper-name ui-wallpaper-name">{{tr(w[1])}}</span><b class="wallpaper-check" v-if="appearance.wallpaperId===w[0]">✓</b></button></div><p class="local-note">{{tr("Tap a wallpaper to preview it. Saved for this conversation.")}}</p></template>
<template v-else><div class="theme-grid"><button v-for="theme in themes" :key="theme" :data-theme="theme" class="theme-card ui-appearance-swatch" :class="'theme-'+theme" :aria-pressed="!appearance.wallpaperId&&(appearance.background||'night')===theme" @click="appearance.background=theme;delete appearance.wallpaperId"><span>{{tr(theme[0]!.toUpperCase()+theme.slice(1))}}</span><i>{{tr(!appearance.wallpaperId&&(appearance.background||'night')===theme?'✓':'')}}</i></button></div><button id="background-done" class="ui-button ui-button--appearance-primary appearance-done" @click="screen='chat'">{{tr("Done")}}</button></template></template>
<template v-else-if="screen==='wallpaper-preview'"><figure class="wallpaper-preview"><img class="appearance-preview-image" :src="asset('04-chat-backgrounds/'+previewWallpaper[0])" :alt="tr(previewWallpaper[1])"><div class="preview-conversation"><span class="appearance-preview-peer">{{tr("A little hello for you.")}}</span><span class="appearance-preview-mine">{{tr("Lovely to meet you!")}}</span></div><figcaption class="appearance-caption">{{tr(previewWallpaper[1])}}</figcaption></figure><div class="wallpaper-apply"><button id="apply-wallpaper" class="ui-button ui-button--appearance-primary appearance-apply" @click="applyBackground('night',previewWallpaper[0])">{{tr("Use this wallpaper")}}</button></div></template>
<template v-else><div class="bubble-preview"><div id="their-bubble">{{tr("A little hello for you.")}}</div><div id="my-bubble">{{tr("Lovely to meet you!")}}</div></div><div class="menu-group"><label v-for="f in bubbleFields" :key="f[0]" class="preference-row ui-appearance-color-row"><span>{{tr(f[1])}}</span><input :id="'color-'+f[0]" type="color" :value="appearance[f[0]!]||f[2]" @input="appearance[f[0]!]=($event.target as HTMLInputElement).value"></label></div><button id="reset-bubbles" class="ui-button ui-button--appearance-reset appearance-reset" @click="resetBubbles">{{tr("Reset to default")}}</button></template>
</div></Transition></template>
<template v-else><input id="message-search" v-model="query" class="c6-search ui-input ui-input--chat-search" :aria-label="tr('Search messages')" :placeholder="locale==='ko'?'이 대화에서 검색':'Search in this conversation'"><div class="c6-results"><p v-if="query&&!searched" class="chat-search-progress">{{tr("Searching…")}}</p><div v-else-if="query&&!results.length" class="chat-search-none"><img class="chat-search-image" :src="asset('01-brand-scenes/envelope')" alt=""><h3 class="chat-search-none-title">{{tr("No messages found.")}}</h3><p class="chat-search-none-copy">{{tr('Every connection starts with a little hello.')}}</p></div><article class="chat-search-result" v-for="m in results" :key="m.id"><small class="chat-search-time">{{new Date(m.createdAt).toLocaleTimeString(locale==='ko'?'ko-KR':'en-US',{hour:'2-digit',minute:'2-digit'})}}</small><p class="chat-search-content">{{m.content}}</p></article></div></template>
<Transition name="c6-panel"><div v-if="safety" class="d3-safety safety-flow ui-scrim" :class="{'ui-scrim--dialog':safety!=='choice'}" @click.self="!busy&&(safety='')"><section :class="[blocked?'safety-unblock-dialog':'',safety==='choice'?'ui-sheet safety-choice-sheet':'ui-dialog ui-dialog--safety safety-confirm-dialog']" role="dialog" aria-modal="true" :aria-label="tr(safety==='choice'?'Report or block':blocked?'Unblock this person?':'Block this person?')"><template v-if="safety==='choice'"><span class="ui-sheet__grabber"></span><h2 class="safety-choice-title">{{tr("Report or block")}}</h2><p class="safety-choice-copy">{{tr("Choose how you would like to manage this person.")}}</p><button id="safety-report" class="d3-choice ui-safety-option" @click="safety='';screen='report'"><img :src="asset('08-interface-icons/icon-flag-light-dialog-22')" alt=""><span class="safety-option-label">{{tr("Report")}}<small class="safety-option-detail">{{tr("Tell us about inappropriate content")}}</small></span></button><button id="safety-block" class="d3-choice ui-safety-option" @click="safety='confirm'"><img :src="asset('11-symbol-icons/icon-block-24-c89c8f')" alt=""><span class="safety-option-label">{{tr("Block")}}<small class="safety-option-detail">{{tr("Stop contact from this person")}}</small></span></button><button class="ui-icon-button ui-icon-button--safety-close safety-choice-close" :aria-label="tr('Cancel')" @click="safety=''">×</button></template><template v-else><button class="ui-icon-button ui-icon-button--reply-close safety-dialog-close" :aria-label="tr('Close dialog')" :disabled="busy" @click="safety=''">×</button><h2 class="safety-dialog-title">{{tr(blocked?'Unblock this person?':'Block this person?')}}</h2><p class="safety-dialog-copy">{{tr(blocked?'You can continue this conversation.':'You will no longer be able to send messages, photos or voice to this person.')}}</p><button id="confirm-block" class="ui-button ui-button--reply safety-confirm-action" :disabled="busy" @click="changeBlock">{{tr(busy?'Saving…':blocked?'Unblock':'Block')}}</button><button class="ui-button ui-button--text safety-dialog-cancel" :disabled="busy" @click="safety=''">{{tr("Cancel")}}</button></template><p v-if="error" role="alert">{{tr(error)}}</p></section></div></Transition>
<Transition name="c6-panel"><div v-if="confirm||editing" class="c6-veil ui-scrim" :class="{'ui-scrim--dialog':confirm}" @click.self="!busy&&(confirm=false,editing=false)"><section class="chat-settings-dialog" :class="confirm?'ui-dialog ui-dialog--chat-clear':'ui-sheet ui-sheet--chat-remark'" role="dialog" aria-modal="true" :aria-label="tr(confirm?'Clear chat history?':'Remark name')"><span v-if="editing" class="ui-sheet__grabber"></span><button class="ui-icon-button ui-icon-button--reply-close chat-dialog-close" :aria-label="tr('Cancel')" :disabled="busy" @click="confirm=false;editing=false">×</button><h2 class="chat-dialog-title">{{confirm?(locale==='ko'?'메시지를 지울까요?':'Clear messages?'):tr('Remark name')}}</h2><p v-if="confirm" class="chat-dialog-copy">{{tr("This only clears your chat history. Your connection and unlocked permissions stay the same.")}}</p><label v-else class="chat-remark-label">{{locale==='ko'?'나에게만 표시':'Only visible to you'}}<input class="ui-input chat-remark-input" v-model="remark" maxlength="60" :aria-label="tr('Remark')" :placeholder="locale==='ko'?'기억하기 쉬운 이름을 입력하세요':'Add a name you’ll remember'"></label><button class="ui-button ui-button--reply chat-dialog-save" :aria-label="tr(busy?'Saving…':confirm?'Clear history':'Save remark')" :class="{'ui-button--chat-clear':confirm}" :disabled="busy" @click="confirm?patch({clearHistory:true}):patch({remark})">{{busy?tr('Saving…'):confirm?(locale==='ko'?'메시지 지우기':'Clear messages'):(locale==='ko'?'저장':'Save')}}</button><button v-if="confirm" class="ui-button ui-button--text chat-dialog-cancel" :disabled="busy" @click="confirm=false;editing=false">{{tr("Cancel")}}</button></section></div></Transition></section>
</template>
<style src="../styles/pages/appearance.css"></style>
<style src="../styles/pages/chat.css"></style>
<style src="../styles/pages/safety.css"></style>
